style.css:
/* Fondo de Misa Amane */
body {
    background: url('https://wallpapers.com/images/hd/misa-amane-golden-poster.jpg') no-repeat center center fixed !important;
    background-size: cover !important;
    color: #f6c85f !important;
    font-family: Cinzel, Georgia, "Times New Roman", serif !important;
}

/* Títulos y texto */
h1, h2, h3, h4, h5, h6, p, span {
    color: #f6c85f !important;
}

/* Enlaces */
a {
    color: #ff9fc8 !important;
    text-decoration: underline !important;
}

a:hover {
    color: #f6c85f !important;
}
